create or replace function public.orbitfs_alert_preview(p_audience text,p_recipient_user_ids uuid[] default null,p_conditions jsonb default '{}'::jsonb) returns jsonb language plpgsql security definer set search_path='public','auth' as $$ declare total integer:=0; sample_json jsonb:='[]'::jsonb; begin if auth.uid() is null then raise exception 'authentication required'; end if; if not public.has_permission('notifications.send') then raise exception 'permission denied'; end if; if p_audience not in ('selected','customers','staff','everyone') then raise exception 'invalid audience'; end if; select count(distinct user_id) into total from public.orbitfs_alert_candidate_recipients(p_audience,p_recipient_user_ids,coalesce(p_conditions,'{}'::jsonb)); select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) into sample_json from (select user_id,max(label) as label,max(email) as email,string_agg(distinct surface,', ' order by surface) as surface from public.orbitfs_alert_candidate_recipients(p_audience,p_recipient_user_ids,coalesce(p_conditions,'{}'::jsonb)) group by user_id order by label limit 8) x; return jsonb_build_object('count',total,'sample',sample_json); end $$; revoke all on function public.orbitfs_alert_preview(text,uuid[],jsonb) from public,anon; grant execute on function public.orbitfs_alert_preview(text,uuid[],jsonb) to authenticated;
